<script setup lang="ts">
import EventCard from '~/components/events/EventCard.vue'
import Select from 'primevue/select'

useSeoMeta({ title: 'Events | Alumni Portal', description: 'Upcoming and past alumni events.' })

const { fetchEvents } = useEvents()

const filter = ref<'upcoming' | 'all'>('upcoming')
const currentPage = ref(1)

const { data: events, refresh, pending } = await useAsyncData('events', () =>
  fetchEvents({ upcoming: filter.value === 'upcoming', page: currentPage.value }),
)

watch(filter, () => {
  currentPage.value = 1
  refresh()
})
</script>

<template>
  <div>
    <div class="bg-white border-b border-slate-200 py-8 px-4">
      <div class="max-w-6xl mx-auto flex items-center justify-between flex-wrap gap-4">
        <div>
          <h1 class="text-2xl font-bold text-slate-900">Events</h1>
          <p class="text-slate-500 text-sm mt-1">Alumni gatherings, workshops, and more</p>
        </div>
        <div class="flex gap-2">
          <button
            v-for="opt in [{ value: 'upcoming', label: 'Upcoming' }, { value: 'all', label: 'All Events' }]"
            :key="opt.value"
            class="px-3 py-1.5 text-sm font-medium rounded-lg transition-colors"
            :class="filter === opt.value ? 'bg-primary-600 text-white' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'"
            @click="filter = opt.value as any"
          >
            {{ opt.label }}
          </button>
        </div>
      </div>
    </div>

    <div class="max-w-6xl mx-auto px-4 py-8">
      <div v-if="pending" class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
        <div v-for="i in 6" :key="i" class="bg-white border border-slate-200 rounded-xl h-64 animate-pulse" />
      </div>
      <div v-else-if="events && events.length > 0" class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
        <EventCard v-for="event in events" :key="event.id" :event="event" />
      </div>
      <div v-else class="text-center py-16">
        <i class="pi pi-calendar text-4xl text-slate-300 mb-3 block" />
        <p class="text-slate-500">No {{ filter === 'upcoming' ? 'upcoming ' : '' }}events found</p>
      </div>
    </div>
  </div>
</template>
